local config = {
  ui_story_31530401_1_dialog_content = "<color=#e8d9bb>1st Legion, New Recruit Camp</color>",
  ui_story_31530401_2_dialog_content = "One, two, three, four!",
  ui_story_31530401_3_dialog_content = "One, two, three—four!",
  ui_story_31530401_4_dialog_content = "Huff... huff... Why does training start before dawn...?",
  ui_story_31530401_5_dialog_content = "Finally... the running is over.",
  ui_story_31530401_6_dialog_content = "*Cough*... Right? We only arrived at the camp hours ago.",
  ui_story_31530401_7_dialog_content = "Have you guys still not realized where we are? This is the 1st Legion of the Illumina Federation—",
  ui_story_31530401_8_dialog_content = "The new recruit training here is said to be the toughest!",
  ui_story_31530401_9_dialog_content = "Oh, stop whining. I heard that the 2nd Legion's training is even more inhumane.",
  ui_story_31530401_10_dialog_content = "By the way, do you know who our instructor is?",
  ui_story_31530401_11_dialog_content = "It's me.",
  ui_story_31530401_12_dialog_content = "C-Commander Sharona!",
  ui_story_31530401_13_dialog_content = "If I remember correctly, the command broadcasted earlier was, \"All new recruits are to run in formation for 3 miles.\"",
  ui_story_31530401_14_dialog_content = "Standing around chatting wasn't included in those orders.",
  ui_story_31530401_15_dialog_content = "Is this what they taught you to do in school?",
  ui_story_31530401_16_dialog_content = "...",
  ui_story_31530401_17_dialog_content = "Alright, new recruits, listen up! You can all thank your fellow gossiping soldiers.",
  ui_story_31530401_18_dialog_content = "Thanks to them, everyone gets to do 100 more squats!",
  ui_story_31530401_19_dialog_content = "Seriously?! I have no more energy...",
  ui_story_31530401_20_dialog_content = "Hmm? Soldiers in the rearmost row, forward march!",
  ui_story_31530401_21_dialog_content = "Uh... Is this the rearmost row?",
  ui_story_31530401_22_dialog_content = "Yes, ma'am! New recruits in the rearmost row, at your command!",
  ui_story_31530401_23_dialog_content = "Hmph. You do know how to report to your superior officer, though.",
  ui_story_31530401_24_dialog_content = "You two! You get 100 more push-ups than the others!",
  ui_story_31530401_25_dialog_content = "Yes, ma'am!",
  ui_story_31530401_26_dialog_content = "1, 2, 3, 4, 5, 6, 7...",
  ui_story_31530401_27_dialog_content = "Incredible...",
  ui_story_31530401_28_dialog_content = "That's a lot of pushups, and all without breaking a sweat!",
  ui_story_31530401_29_dialog_content = "(This new recruit... Why does she look familiar?)",
  ui_story_31530401_30_dialog_content = "Reporting in, ma'am! 100 push-ups done, training complete!",
  ui_story_31530401_31_dialog_content = "Excellent! Tell the person next to you to hurry up... Wait! Grand Marshal Reinhardt?!",
  ui_story_31530401_32_dialog_content = "What? The Grand Marshal is here?",
  ui_story_31530401_33_dialog_content = "It really is the Grand Marshal! She looks even more impressive in real life!",
  ui_story_31530401_34_dialog_content = "I can't believe I ran 3 miles alongside the Grand Marshal!",
  ui_story_31530401_35_dialog_content = "And the one next to her is... PlayerName? Why are you here too?",
  ui_story_31530401_36_dialog_content = "Uh, I think... I came here to help take notes.",
  ui_story_31530401_37_dialog_content = "And then I don't know what ended up happening either.",
  ui_story_31530401_38_dialog_content = "I just followed the Grand Marshal quietly and blended into the ranks of new recruits...",
  ui_story_31530401_39_dialog_content = "Haha, you can't truly understand it without experiencing it yourself.",
  ui_story_31530401_40_dialog_content = "Now you're more aware of the effort each Illumina soldier puts into training behind-the-scenes.",
  ui_story_31530401_41_dialog_content = "Grand Marshal, apologies. I was not told that you would come observe. Please forgive my earlier impoliteness.",
  ui_story_31530401_42_dialog_content = "Commander Sharona, it is your duty to oversee the discipline of the new recruits.",
  ui_story_31530401_43_dialog_content = "You haven't done anything wrong, so there's no need for apologies.",
  ui_story_31530401_44_dialog_content = "As long as I stand in formation, I'm obligated to listen to the drill instructor's commands.",
  ui_story_31530401_45_dialog_content = "Yes, ma'am!",
  ui_story_31530401_46_dialog_content = "But as for Navigator...",
  ui_story_31530401_47_dialog_content = "He's just a guest who came to accompany me on my inspection, not a soldier who's been through training.",
  ui_story_31530401_48_dialog_content = "A 3-mile run is more than enough for him.",
  ui_story_31530401_49_dialog_content = "I'll finish the rest of his training in his stead.",
  ui_story_31530401_50_option_content = "Thank you, Grand Marshal.",
  ui_story_31530401_51_dialog_content = "But rather than finishing it in my stead, why not get Sharona to exempt me from the training altogether?",
  ui_story_31530401_52_dialog_content = "PlayerName, the words of an Illumina Legion Commander shouldn't be taken in jest.",
  ui_story_31530401_53_dialog_content = "Not to mention, training is actually a commendation for soldiers.",
  ui_story_31530401_54_dialog_content = "Every minute of training improves our strength on the battlefield.",
  ui_story_31530401_55_dialog_content = "One more minute of training means one more bit of strength.",
  ui_story_31530401_56_dialog_content = "I'm always willing to receive more training!",
  ui_story_31530401_57_option_content = "You don't have to be thoughtful like that.",
  ui_story_31530401_58_dialog_content = "I haven't gone through training but I did stand in the formation just now...",
  ui_story_31530401_59_dialog_content = "It was my fault for speaking freely without permission.",
  ui_story_31530401_60_dialog_content = "I wouldn't feel comfortable having you take the punishment in my place.",
  ui_story_31530401_61_dialog_content = "I'll do it myself!",
  ui_story_31530401_62_dialog_content = "Hahaha, well, since the inexperienced Caelestite says so...",
  ui_story_31530401_63_dialog_content = "I can't just stand around waiting to be defeated!",
  ui_story_31530401_64_dialog_content = "PlayerName, I accept your training challenge!",
  ui_story_31530401_65_dialog_content = "How did this become a challenge...?",
  ui_story_31530401_66_dialog_content = "Even the Grand Marshal is training so hard... I-I'll join in too!",
  ui_story_31530401_67_dialog_content = "I want to improve my abilities too!",
  ui_story_31530401_68_dialog_content = "Instructor! We all want extra training!",
  ui_story_31530401_69_dialog_content = "(The new recruits who were complaining are now in high spirits, like they're completely different people...)",
  ui_story_31530401_70_dialog_content = "(Is this the power of Reinhardt's influence?)",
  ui_story_31530401_71_dialog_content = "(But I didn't expect Reinhardt's inspection to be...)",
  ui_story_31530401_72_dialog_content = "(So tiring!)",
  ui_story_31530401_73_dialog_content = "PlayerName, it's almost dawn. Time to head for our next stop.",
  ui_story_31530401_74_dialog_content = "<color=#e8d9bb>Gannon City, Research Center</color>",
  ui_story_31530401_75_dialog_content = "Those are the results of our research in the past few days. Naturally, we'll continue iterating upon our projects in the future.",
  ui_story_31530401_76_dialog_content = "(A game machine model with no content whatsoever, a colorful field of roses, an observation record of Hiiro...)",
  ui_story_31530401_77_dialog_content = "(I'm no expert but... can these actually be called research results?)",
  ui_story_31530401_78_dialog_content = "Scientific research requires more patience and resilience than the average individual possesses.",
  ui_story_31530401_79_dialog_content = "Sometimes it also requires some luck, and time.",
  ui_story_31530401_80_dialog_content = "I've always admired our colleagues at the Illumina Research Center.",
  ui_story_31530401_81_dialog_content = "I'm honored to have had the opportunity to see the results of your research today. It left a huge impression on me!",
  ui_story_31530401_82_dialog_content = "Gronru's game machine doesn't have any actual content yet...",
  ui_story_31530401_83_dialog_content = "But I'm guessing you're trying to create a simulated combat system for the people of Illumina to fight Eclipsites.",
  ui_story_31530401_84_dialog_content = "A brilliant combination of education and entertainment, plus it would improve everyone's combat skills against Eclipsites.",
  ui_story_31530401_85_dialog_content = "I'm impressed with your long-term vision!",
  ui_story_31530401_86_dialog_content = "Really? Ha... Ha...",
  ui_story_31530401_87_dialog_content = "And these deceptively beautiful rose variants Jola is cultivating...",
  ui_story_31530401_88_dialog_content = "Their thorns are actually a hundred times sharper than ordinary roses.",
  ui_story_31530401_89_dialog_content = "If they could be planted at the frontline, they'd effectively slow the speed of oncoming Eclipsites.",
  ui_story_31530401_90_dialog_content = "(Why didn't I think of that?)",
  ui_story_31530401_91_dialog_content = "(Although it'd be a cruel fate for these beautiful flowers...)",
  ui_story_31530401_92_dialog_content = "(But this means I finally have a feasible research plan to submit!)",
  ui_story_31530401_93_dialog_content = "I'm just a soldier.",
  ui_story_31530401_94_dialog_content = "I'm deeply moved by the innovation and creativity of your research.",
  ui_story_31530401_95_dialog_content = "Scientific research is like a mountain you scale, always striving to reach its peak despite facing countless obstacles.",
  ui_story_31530401_96_dialog_content = "All across time, researchers have been the heart of the Illumina Federation. Without any of you...",
  ui_story_31530401_97_dialog_content = "There would not be a single meal for the people of Illumina, nor a single gun in the hands of Illuminan soldiers.",
  ui_story_31530401_98_dialog_content = "Don't hold back when requesting next year's research funding! I will fully support it!",
  ui_story_31530401_99_dialog_content = "Grand Marshal, I'm going to cultivate a new type of combat rose immediately!",
  ui_story_31530401_100_dialog_content = "If the idea of the Eclipsite combat game can be realized, it means we can compete with more people in real time, right?",
  ui_story_31530401_101_dialog_content = "Things are getting really interesting. I'm going to speed up...",
  ui_story_31530401_102_dialog_content = "We're also going make our research records on Commander Hiiro more in-depth!",
  ui_story_31530401_103_dialog_content = "Huh? Ah... M-Me too... I'll also... conduct some experiments...",
  ui_story_31530401_104_dialog_content = "(Everyone had seemed depressed about their research results, but now there's a renewed fighting spirit in their eyes...)",
  ui_story_31530401_105_dialog_content = "(Is this... Reinhardt's magic?)",
  ui_story_31530401_106_dialog_content = "Should we also take our leave?",
  ui_story_31530401_107_dialog_content = "Huh?",
  ui_story_31530401_108_dialog_content = "To the next place!",
  ui_story_31530401_109_dialog_content = "<color=#e8d9bb>Illumina: The Frontline</color>",
  ui_story_31530401_110_dialog_content = "Hiiro, I'll lead a team to the front to dig trenches.",
  ui_story_31530401_111_dialog_content = "The other teams will follow your original plan!",
  ui_story_31530401_112_dialog_content = "Yes, Grand Marshal!",
  ui_story_31530401_113_dialog_content = "PlayerName, grab a shovel and follow me.",
  ui_story_31530401_114_dialog_content = "Huh? Are we going to the frontlines to dig trenches?",
  ui_story_31530401_115_dialog_content = "Does all this really happen in one day...?",
  ui_story_31530401_116_dialog_content = "Fellow Illuminans! The war is cruel, and fear in the face of battle is but our instinctive reaction.",
  ui_story_31530401_117_dialog_content = "The battle that just ended was a great victory for us.",
  ui_story_31530401_118_dialog_content = "Everyone conquered their fears and persevered to the end.",
  ui_story_31530401_119_dialog_content = "Each and every one of you is a hero. You are the pride of Illumina!",
  ui_story_31530401_120_dialog_content = "However, final victory is not yet upon us.",
  ui_story_31530401_122_dialog_content = "New trenches are waiting to be dug by us! New battlefronts are waiting to be defined by us!",
  ui_story_31530401_123_dialog_content = "Now, let us continue to devote ourselves to the battles to come!",
  ui_story_31530401_124_dialog_content = "Grand Marshal! Grand Marshal! Grand Marshal!",
  ui_story_31530401_125_dialog_content = "(The soldiers who were demoralized by the earlier attack have bright eyes once again.)",
  ui_story_31530401_126_dialog_content = "(Reinhardt...)",
  ui_story_31530401_127_dialog_content = "Let's go!",
  ui_story_31530401_128_dialog_content = "Charge!",
  ui_story_31530401_129_dialog_content = "Charge!",
  ui_story_31530401_130_dialog_content = "<color=#e8d9bb>Gannon City, Administrative District</color>",
  ui_story_31530401_131_dialog_content = "C-Charge...",
  ui_story_31530401_132_dialog_content = "Hahaha, we're not at the frontlines anymore. Where are you planning to charge to?",
  ui_story_31530401_133_dialog_content = "Oh, r-right.",
  ui_story_31530401_134_dialog_content = "... Sorry, I probably haven't gotten back to my senses.",
  ui_story_31530401_135_dialog_content = "Sit here and rest for a while. You can summarize all today's notes while you rest.",
  ui_story_31530401_136_dialog_content = "I'm going to the conference room for a meeting. It should be quick.",
  ui_story_31530401_137_dialog_content = "O-Okay!",
  ui_story_31530401_138_dialog_content = "(Reinhardt dug trenches with the soldiers for hours earlier...)",
  ui_story_31530401_139_dialog_content = "(And they even dug out double the expected length!)",
  ui_story_31530401_140_dialog_content = "(Ugh... I can't do this anymore though. It's too much for my body...!)",
  ui_story_31530401_141_dialog_content = "*Snore*",
  ui_story_31530401_142_dialog_content = "PlayerName?",
  ui_story_31530401_143_dialog_content = "Stop zoning out and come in for the meeting.",
  ui_story_31530401_144_dialog_content = "Meeting? Do I have to go too? W-Who else is attending?",
  ui_story_31530401_145_dialog_content = "Hahaha, you'll know when you come in.",
  ui_story_31530401_146_dialog_content = "Oh...",
  ui_story_31530401_147_dialog_content = "PlayerName, you haven't even completed your 60-mile run. Why are you leaving already?",
  ui_story_31530401_148_dialog_content = "Tsk, PlayerName, why not come train under me? My training's not any less intense than Sharona's!",
  ui_story_31530401_149_dialog_content = "Uh oh, the frontline has been breached by Eclipsites... PlayerName, requesting support!",
  ui_story_31530401_150_dialog_content = "Don't go, PlayerName.",
  ui_story_31530401_151_dialog_content = "Try my super strategic connecting game to beat Eclipsites first!",
  ui_story_31530401_152_dialog_content = "One at a time, everyone...",
  ui_story_31530401_153_dialog_content = "One at a time...",
  ui_story_31530401_154_dialog_content = "<color=#e8d9bb>Bam!</color>",
  ui_story_31530401_155_dialog_content = "*Snore*",
  ui_story_31530401_156_dialog_content = "(That was frightening. It was just a dream...)",
  ui_story_31530401_157_dialog_content = "You're finally awake.",
  ui_story_31530401_158_dialog_content = "(Huh? Reinhardt's meeting is over already?)",
  ui_story_31530401_159_dialog_content = "(But she... Why does she look so angry?)",
  ui_story_31530401_160_dialog_content = "(Oh no... She asked me to make a summary of my notes, but I fell asleep without writing a word...)",
  ui_story_31530401_161_dialog_content = "(Reinhardt must be angry because of this...)",
  ui_story_31530401_162_dialog_content = "(What do I do now? Someone help me, please...)",
  ui_story_31530401_163_dialog_content = "<color=#e8d9bb>*stomach growl*</color>",
  ui_story_31530401_164_dialog_content = "Huh? Was that...",
  ui_story_31530401_165_dialog_content = "Ahem. Sorry, looks like my stomach's protesting.",
  ui_story_31530401_166_dialog_content = "We still have time. Let's go to the canteen!",
  ui_story_31530401_167_dialog_content = "Okay...",
  ui_story_31530401_168_dialog_content = "(Why is she so quiet? She must still be angry.)",
  ui_story_31530401_169_dialog_content = "(The atmosphere is so awkward...)",
  ui_story_31530401_170_dialog_content = "Um... I'm so sorry!",
  ui_story_31530401_171_dialog_content = "Huh? Why are you saying sorry?",
  ui_story_31530401_172_dialog_content = "I was way too tired earlier... so I didn't finish writing today's summary...",
  ui_story_31530401_173_dialog_content = "Please don't be mad... I'll find time to complete it!",
  ui_story_31530401_174_dialog_content = "Me? Mad?",
  ui_story_31530401_175_dialog_content = "Hahahaha, sorry, sorry! I can't help frowning when I'm hungry.",
  ui_story_31530401_176_dialog_content = "Vivian has been reprimanding me about this for a long time, but I haven't kicked the habit.",
  ui_story_31530401_177_dialog_content = "Oh! I see.",
  ui_story_31530401_178_option_content = "That's a relief.",
  ui_story_31530401_179_dialog_content = "Hmm? You're happy that I didn't get rid of this bad habit of mine?",
  ui_story_31530401_180_dialog_content = "That's... Sorry, no! That's not what I meant!",
  ui_story_31530401_181_dialog_content = "But I don't think it's really a bad habit.",
  ui_story_31530401_182_option_content = "What an interesting habit.",
  ui_story_31530401_183_dialog_content = "It feels like the ever-perfect Grand Marshal seems a little closer to us normal people now.",
  ui_story_31530401_184_dialog_content = "Ever-perfect? I wouldn't say that about myself.",
  ui_story_31530401_185_dialog_content = "How are you not? You did as much in one day today as I do in one month!",
  ui_story_31530401_186_dialog_content = "And every single task was handled perfectly, without flaws.",
  ui_story_31530401_187_dialog_content = "No wonder the people of Illumina lionize the Grand Marshal so much.",
  ui_story_31530401_188_dialog_content = "I saw it with my own eyes today. You must know some kind of magic to manipulate people's minds!",
  ui_story_31530401_189_dialog_content = "Hahahaha, PlayerName, you have quite the imagination!",
  ui_story_31530401_190_dialog_content = "A new recruit's job is to train, a researcher's job is to experiment...",
  ui_story_31530401_191_dialog_content = "And the Grand Marshal's job is to strategize the way forward when people lose their way.",
  ui_story_31530401_192_dialog_content = "If you insist on saying I have some sort of magical ability, I can only say—",
  ui_story_31530401_193_dialog_content = "That makes the two of us!",
  ui_story_31530401_194_dialog_content = "Huh?",
  ui_story_31530401_195_dialog_content = "The legendary last Caelestite lacks physical strength and is, for lack of a better word, fragile.",
  ui_story_31530401_196_dialog_content = "Yet you're able to get so many people to join you on your adventures.",
  ui_story_31530401_197_dialog_content = "Even Vivian's subordinate, Vice, is willing to follow you on your wanderings across the world.",
  ui_story_31530401_198_dialog_content = "Do you also use magic to lure people towards you?",
  ui_story_31530401_199_dialog_content = "That's...",
  ui_story_31530401_200_dialog_content = "<color=#e8d9bb>*stomach growl*</color>",
  ui_story_31530401_201_dialog_content = "Hahaha! Looks like your stomach's started protesting too, huh?",
  ui_story_31530401_202_dialog_content = "Come on, let's satisfy them first.",
  ui_story_31530401_203_dialog_content = "Then we'll go back and finish the rest of the paperwork, and continue this conversation afterwards!",
  ui_story_31530401_204_dialog_content = "(We're going to keep working?!)",
  ui_story_31530401_205_dialog_content = "(When will this day be over...)",
  ui_story_31530401_206_dialog_content = "(Reinhardt's not a Grand Marshal, I'm pretty sure she's some kind of inexhaustible creature.)",
  ui_story_31530401_207_dialog_content = "Woo-hoo!",
  ui_story_31530401_208_dialog_content = "Yummy! Pot roast is the best!",
  ui_story_31530401_209_dialog_content = "Another serving, please!",
  ui_story_31530601_1_dialog_content = "Is that young man the legendary Caelestite?",
  ui_story_31530601_2_dialog_content = "No way, he looks way too shabby to be any kind of legend.",
  ui_story_31530601_3_dialog_content = "Everyone's got their own tastes. Maybe he just prefers to look like this?",
  ui_story_31530601_4_dialog_content = "But as the sole survivor of an entire race, he must've inherited some kind of fortune, right? He even owns all of Eraveil—",
  ui_story_31530601_5_dialog_content = "(They've been staring at me all this time... And now they're starting to say some really wild things.)",
  ui_story_31530601_6_dialog_content = "(Is this really the right place? Why would she invite me to such a ritzy banquet...?)",
  ui_story_31530601_7_dialog_content = "\"Dear PlayerName,\"",
  ui_story_31530601_8_dialog_content = "\"If you have time, could you please come to Umbraton this weekend? The address is #XXX on XXXX Street. P.S. Even if you don't have the time, please do your best to show up.\"",
  ui_story_31530601_9_dialog_content = "Pardon me, but are you the representative from Eraveil?",
  ui_story_31530601_10_dialog_content = "Huh?!",
  ui_story_31530601_11_dialog_content = "I know you. You're the last Caelestite, inheriting the most evil power of your race.",
  ui_story_31530601_12_dialog_content = "You control the minds of any living creature on Astra! With a single whim, you can turn everyone in this room into your puppet!",
  ui_story_31530601_13_dialog_content = "Now just hang on a second!",
  ui_story_31530601_14_dialog_content = "Turn us into puppets, you say? Sorry, but wealth and status are already more than capable of accomplishing that. Pay these people no heed, my friend; you'll find that some nobles are a cut above the rest.",
  ui_story_31530601_15_dialog_content = "No one wants to make friends with filth, but I can help you in that regard.",
  ui_story_31530601_16_dialog_content = "I-I can take care of myself, thanks...",
  ui_story_31530601_17_dialog_content = "What? The Caelestite? Where?! Let me see, let me see—",
  ui_story_31530601_18_dialog_content = "—Ladies and gentlemen.",
  ui_story_31530601_19_dialog_content = "(That voice...!)",
  ui_story_31530601_20_dialog_content = "Approaching him is perfectly acceptable, but I ask that you conduct yourselves with a bit more dignity.",
  ui_story_31530601_21_dialog_content = "If for no other reason, then at least do it for me. After all—",
  ui_story_31530601_22_dialog_content = "PlayerName is here at my request.",
  ui_story_31530601_23_dialog_content = "Reinhardt...! You really are here!",
  ui_story_31530601_24_dialog_content = "(And in such a formal outfit too...)",
  ui_story_31530601_25_dialog_content = "The Grand Marshal of Illumina! She invited the Caelestite...",
  ui_story_31530601_26_dialog_content = "And the Caelestite addressed her by name...",
  ui_story_31530601_27_dialog_content = "Mr. PlayerName, you must come to our family's next ball!",
  ui_story_31530601_28_dialog_content = "We would be honored to have you as our guest!",
  ui_story_31530601_29_dialog_content = "This way, PlayerName.",
  ui_story_31530601_30_dialog_content = "(... I'm saved!)",
  ui_story_31530601_31_dialog_content = "<color=#e8d9bb>The crowd instinctively parted, and all eyes were glued to their every step as they ascended the stairs.</color>",
  ui_story_31530601_32_dialog_content = "... Sorry about that. I was in the middle of an important meeting, and I couldn't break away in time to save you from those people.",
  ui_story_31530601_33_dialog_content = "Don't worry about it! If it wasn't for that, I never would've known how ridiculous the rumors about me have gotten.",
  ui_story_31530601_34_dialog_content = "Apparently, I'm a wealthy villain capable of enslaving every single mind on Astra... After today, I wouldn't be surprised if they started accusing Illumina of being in cahoots with Eraveil!",
  ui_story_31530601_35_dialog_content = "Hahaha, then it looks like I was worrying for nothing! Good, I like seeing this <color=#FFB400>free and unruly</color> side of you.",
  ui_story_31530601_36_dialog_content = "I'm not sure if that was a compliment or not...",
  ui_story_31530601_37_dialog_content = "You're a lot different than usual today. I'm having a hard time getting a read on you now.",
  ui_story_31530601_38_dialog_content = "Different? Are you saying I'm cooler than usual?",
  ui_story_31530601_39_dialog_content = "I was just about to say that! But... yes, your coolness and your presence feel a lot different, kind of like—",
  ui_story_31530601_40_dialog_content = "You're about to say something tough, \"Not bad, now start making these weapons!\" or \"I want his profile on my desk in ten minutes.\"",
  ui_story_31530601_41_dialog_content = "... I don't think the Grand Marshal of Illumina should seem that way to anyone!",
  ui_story_31530601_42_dialog_content = "But that's how it felt when you rescued me from the crowd... It was so cool!",
  ui_story_31530601_43_dialog_content = "Those people are nothing like you. All they care about is their own interests... But that's okay, since the world still needs people like them.",
  ui_story_31530601_44_dialog_content = "I'll handle them, so please live freely and to your heart's content.",
  ui_story_31530601_45_dialog_content = "That's something only you can do.",
  ui_story_31530601_46_dialog_content = "Only me...?",
  ui_story_31530601_47_dialog_content = "I was surprised to learn that Reinhardt had invited a guest tonight—but considering it's PlayerName, I completely understand.",
  ui_story_31530601_48_dialog_content = "Shadowlord...!",
  ui_story_31530601_49_dialog_content = "(So, the important meeting was between him and Reinhardt?)",
  ui_story_31530601_50_dialog_content = "Being the Shadowlord must be taxing at times. Illumina's soldiers are generally upright and simple, which makes dealing with them fairly straightforward. You, on the other hand, have to contend with those people downstairs.",
  ui_story_31530601_51_dialog_content = "In my opinion, inspiring and leading the upright and simple masses is a much more daunting job.",
  ui_story_31530601_52_dialog_content = "Today's negotiations would have been impossible without your presence.",
  ui_story_31530601_53_dialog_content = "I can only do a third of the work, so I'll give it my very best.",
  ui_story_31530601_54_dialog_content = "The rest is up to you and Lady Carleen.",
  ui_story_31530601_55_dialog_content = "(Carleen was there too?! I wonder where she is now...?)",
  ui_story_31530601_56_dialog_content = "Grand Marshal Reinhardt! And PlayerName, my dear friend!",
  ui_story_31530601_57_dialog_content = "(When did we become friends?!)",
  ui_story_31530601_58_dialog_content = "Would you like to join my friends and me for a brief chat? They're nobles from Lumopolis, you see, and—",
  ui_story_31530601_59_dialog_content = "What were you saying just now, PlayerName? That Eclipsites had infiltrated the Colossus? Don't worry, I'll help you root them out!",
  ui_story_31530601_60_dialog_content = "Huh?! Ah... Th-That's right! Tons of Eclipsites! Vice has been fending them off for three days now! We could really use your help!",
  ui_story_31530601_61_dialog_content = "As you can see, my good man, our friend is in dire need of assistance. If you'll please excuse us, we must be going.",
  ui_story_31530601_62_dialog_content = "Please be careful. I'll be sure to notify Lady Carleen about your situation.",
  ui_story_31530601_63_dialog_content = "Ah, back in Gannon City!",
  ui_story_31530601_64_dialog_content = "I used to think this place was so cramped and suffocating, but after that banquet, every breath of air felt so refreshing!",
  ui_story_31530601_65_dialog_content = "...",
  ui_story_31530601_66_dialog_content = "(... Whoops! I wasn't supposed to say that out loud!)",
  ui_story_31530601_67_dialog_content = "Don't worry, I'm not gonna upset about what you said about Gannon City.",
  ui_story_31530601_68_dialog_content = "She saw right through me!",
  ui_story_31530601_69_dialog_content = "Besides, for someone as free as yourself, this place would definitely feel cramped and stuffy.",
  ui_story_31530601_70_dialog_content = "No one... should ever get used to living like this.",
  ui_story_31530601_71_dialog_content = "... Can I ask why you invited me to that banquet in Umbraton today? Or why you asked me to fly you back to Gannon City before it was over?",
  ui_story_31530601_72_dialog_content = "Y-You weren't planning to use me as an excuse to leave, right?",
  ui_story_31530601_73_dialog_content = "You're my dear friend and a dependable ally. Why would I poke fun at you like that?",
  ui_story_31530601_74_dialog_content = "The reason I asked you to come is... Watch out!",
  ui_story_31530601_75_dialog_content = "(That was close... I nearly got run over by that transport vehicle! I should pay more attention to my surroundings...)",
  ui_story_31530601_76_dialog_content = "Watch where you're going. Gannon's newest sector doesn't need any living sacrifices.",
  ui_story_31530601_77_dialog_content = "I-I'm sorry! Wait, newest sector? Are you guys developing a new area?",
  ui_story_31530601_78_dialog_content = "Now that you mention it... that transport vehicle was carrying a bunch of plants, wasn't it? I don't think I've ever seen a single plant in Gannon City before.",
  ui_story_31530601_79_dialog_content = "Heheh.",
  ui_story_31530601_80_dialog_content = "... Am I actually imagining things?! That laugh almost sounded like you were pleased with yourself!",
  ui_story_31530601_81_dialog_content = "You'll know once you see it for yourself. Come with me!",
  ui_story_31530601_82_dialog_content = "I-Is this still... Gannon City?",
  ui_story_31530601_83_dialog_content = "I can't believe it...",
  ui_story_31530601_84_dialog_content = "I can assure you that this is still Gannon City. Welcome to our newest residential sector.",
  ui_story_31530601_85_dialog_content = "When we designed this place, we wanted it to be something that even a free and unruly Caelestite would admire.",
  ui_story_31530601_86_dialog_content = "Me? But why? Not to make excuses for my shortcomings or anything, but there are plenty of other free and unruly people in the world.",
  ui_story_31530601_87_dialog_content = "I don't see it as a shortcoming at all.",
  ui_story_31530601_88_dialog_content = "You're used to living in the wide-open world, and enjoy a sense of independence that lets you see everything it has to offer—",
  ui_story_31530601_89_dialog_content = "That's what it means to be free and unruly. It's not a shortcoming; it's a rare form of happiness that few people will ever experience.",
  ui_story_31530601_90_dialog_content = "And that happiness is something I want to provide for every person in Illumina.",
  ui_story_31530601_91_dialog_content = "!!!",
  ui_story_31530601_92_dialog_content = "For centuries, the people of Illumina have lived such frugal lives underground, all in preparation for a never-ending war.",
  ui_story_31530601_93_dialog_content = "We have no choice but to live like this, but that doesn't mean we don't deserve better.",
  ui_story_31530601_94_dialog_content = "Which is why I proposed a new plan to improve the lives of our citizens. This newest sector is the test site for this plan.",
  ui_story_31530601_95_dialog_content = "PlayerName, would you help me?",
  ui_story_31530601_96_dialog_content = "As Illumina's ally, and the freest person in the world—",
  ui_story_31530601_97_dialog_content = "Please give me an honest evaluation of our newest sector. Your insight is something that I value greatly.",
  ui_story_31530601_98_dialog_content = "Reinhardt... I'm amazed that you came up with something so incredible!",
  ui_story_31530601_99_dialog_content = "Of course I'll help you! B-But I'm not exactly sure how to evaluate this place...",
  ui_story_31530601_100_dialog_content = "It's simple. Just give me your most honest opinion about it.",
  ui_story_31530601_101_dialog_content = "Wait! On the other side of the street... Is that an auto vendor?",
  ui_story_31530601_102_dialog_content = "I heard that you and your friends uncovered something like this in an ancient Undercity. It piqued my curiosity, so I had Gronru put together a test model.",
  ui_story_31530601_103_dialog_content = "Well? Is it anything like the original?",
  ui_story_31530601_104_dialog_content = "Let's find out. One breakfast bar, please...",
  ui_story_31530601_105_dialog_content = "It actually came out!",
  ui_story_31530601_106_dialog_content = "This is amazing! Food has always been rationed here in Gannon City, but now it can be served on demand...",
  ui_story_31530601_107_dialog_content = "It's just a matter of course. Now that our resources are plentiful enough to sustain us, accessibility and convenience become our next priorities. Besides, no one likes to queue up for things.",
  ui_story_31530601_108_dialog_content = "Let's move on to the next street.",
  ui_story_31530601_109_dialog_content = "What a beautiful-looking park! I've never seen anything so green in Gannon City before...",
  ui_story_31530601_110_dialog_content = "Migard claims that these plants are all capable of growing well under artificial lighting.",
  ui_story_31530601_111_dialog_content = "I keep two in my quarters as well. If someone like me can keep them alive, then the rest of Gannon City shouldn't have a problem doing the same!",
  ui_story_31530601_112_dialog_content = "And all of these jumping platforms and training equipment... Are they for exercising?",
  ui_story_31530601_113_dialog_content = "Good eye. In fact, I'm proud to call these some of my greatest work.",
  ui_story_31530601_114_dialog_content = "Even someone who avoids exercise might be tempted to give these a try. Don't you think?",
  ui_story_31530601_115_dialog_content = "Come on, you should try it out. I'll help you!",
  ui_story_31530601_116_dialog_content = "I-I'm good, but... I can tell that this place has changed. I could even describe it as \"vibrant\" now...",
  ui_story_31530601_117_dialog_content = "... Wait, I get it now! You went to that banquet in Umbraton for the sake of this new sector, didn't you?",
  ui_story_31530601_118_dialog_content = "Correct! Illumina has become far too militarized, so much so that certain daily necessities have become scarce.",
  ui_story_31530601_119_dialog_content = "If we really wish to expand, we'll need the backing of both Umbraton and Lumopolis.",
  ui_story_31530601_120_dialog_content = "You don't want food bars to be the only thing in our auto vendors, right?",
  ui_story_31530601_121_dialog_content = "So that's why you were meeting with Carleen and Istvan...",
  ui_story_31530601_122_dialog_content = "A business proposal that would benefit all three parties—that's the agreement we reached back then.",
  ui_story_31530601_123_dialog_content = "But naturally, an agreement between three leaders won't be enough. Nobles, guilds, gangs... What matters most is having all of them on board, as well.",
  ui_story_31530601_124_dialog_content = "Is that why all of those rich and important people were there too?",
  ui_story_31530601_125_dialog_content = "Of course. After all, which of them could afford to miss out on a business opportunity like this? To be honest, I'm not very good at dealing with them, same as you.",
  ui_story_31530601_126_dialog_content = "But I'll definitely get the hang of it someday. Even the most cunning merchants are nothing compared to the stubborn old people I have to work with every day.",
  ui_story_31530601_127_dialog_content = "Determined, capable, and tactful... That's the Grand Marshal of Illumina.",
  ui_story_31530601_128_dialog_content = "But that's a lot to handle all by yourself... Won't you feel exhausted?",
  ui_story_31530601_129_dialog_content = "I hardly think so. After all, I'm not the one driving transport vehicles or tending to the plants.",
  ui_story_31530601_130_dialog_content = "That doesn't mean your plate isn't full. You mentioned Gronru and Migard, as well as this place having \"some of your greatest work\"...",
  ui_story_31530601_131_dialog_content = "There's no use denying it. You have your hands in almost every aspect of the new sector's development!",
  ui_story_31530601_132_dialog_content = "A-Ahem... It's important to monitor every step of a process like this... Besides, I'm not looking for personal compliments here.",
  ui_story_31530601_133_dialog_content = "I'm asking for your honest opinion about this place.",
  ui_story_31530601_134_dialog_content = "Don't look at me as the Grand Marshal, but as another friend and comrade-in-arms, and tell me exactly how you feel about it. Even harsh criticism is totally fine!",
  ui_story_31530601_135_option_content = "I really think the new sector is amazing.",
  ui_story_31530601_136_dialog_content = "It's so calm and peaceful. Even someone as serious as you feel relaxed enough to chat this much with me here. Isn't that the whole point?",
  ui_story_31530601_137_dialog_content = "You think... I feel relaxed?",
  ui_story_31530601_138_option_content = "I think you're expecting too much of yourself.",
  ui_story_31530601_139_dialog_content = "After hearing you talk about the new sector, I can tell that you've given a lot to this place. You sound so happy and proud, as if you're introducing something you love very much.",
  ui_story_31530601_140_dialog_content = "I sound... happy?",
  ui_story_31530601_141_dialog_content = "You mean you didn't realize it?",
  ui_story_31530601_142_dialog_content = "You mentioned so many things about yourself just now. How you hate waiting in line, or how you can't take care of plants... And how proud you feel when things get done.",
  ui_story_31530601_143_dialog_content = "Haha... Hahahahaha!",
  ui_story_31530601_144_dialog_content = "I knew inviting you here was the right choice!",
  ui_story_31530601_145_dialog_content = "Ah... I can't remember the last time I laughed this hard.",
  ui_story_31530601_146_dialog_content = "I think it was when they were still around...",
  ui_story_31530601_147_dialog_content = "They? You mean...",
  ui_story_31530601_148_dialog_content = "My sister, as well as Helios.",
  ui_story_31530601_149_dialog_content = "We used to do everything together. Studying, training, and living our lives.",
  ui_story_31530601_150_dialog_content = "In our spare time, we'd also come to places like this and stare out at Gannon City from up high. We'd talk about all sorts of pointless things, laughing as we enjoyed the breeze.",
  ui_story_31530601_151_dialog_content = "Thinking back on that time makes me feel so nostalgic.",
  ui_story_31530601_152_dialog_content = "Reinhardt...",
  ui_story_31530601_153_dialog_content = "But don't worry. Nothing can ever stay the same, and while some changes can really weigh us down—",
  ui_story_31530601_154_dialog_content = "More often than not, change is exciting.",
  ui_story_31530601_155_dialog_content = "Just look at Gannon City: it's changing from a cramped and stifling place to a vibrant and open city, isn't it?",
  ui_story_31530601_156_dialog_content = "And according to your imagination, even I seem more relaxed and talkative now.",
  ui_story_31530601_157_dialog_content = "I wasn't imagining anything!",
  ui_story_31530601_158_dialog_content = "Heheh. You're quite an incredible person yourself.",
  ui_story_31530601_159_dialog_content = "After all these years, you helped me remember what it feels like to chat and laugh with my friends... And that's more than enough for me.",
  ui_story_31530601_160_dialog_content = "... Reinhardt?",
  ui_story_31530601_161_dialog_content = "But Denier and Helios aren't with me anymore... And after today, you'll go back to flying all over the world again.",
  ui_story_31530601_162_dialog_content = "And I'll be here, watching over all of Gannon City.",
  ui_story_31530601_163_dialog_content = "I'll bear witness to the rise of this new sector, a green and vibrant space for everyone to enjoy.",
  ui_story_31530601_164_dialog_content = "It is a place where our people can live without restraint and pick and choose the things they want to eat.",
  ui_story_31530601_165_dialog_content = "For the citizens of Illumina, training isn't just our duty; it's also a hobby and a way of staying healthy.",
  ui_story_31530601_166_dialog_content = "Here, the kids can climb up to the highest places and spend precious time with their friends, laughing and gazing at the city as we once did. No war or strife will reach them here.",
  ui_story_31530601_167_dialog_content = "As Grand Marshal of the Illumina Federation... I vow to watch over everything.",
  ui_story_31530601_168_dialog_content = "I'll always be here.",
  ui_story_31530601_169_dialog_content = "(The Enlightened Illumination... I see now.)",
  ui_story_31530601_170_dialog_content = "(It's impossible to see this person as just another good friend. She's so much more than that.)",
  ui_story_31530601_171_dialog_content = "Now then, my <color=#FFB400>free and unruly</color> friend... Since you have such a high opinion of this place, perhaps we could swap a plot of land in Eraveil for a neighborhood here? What do you think?",
  ui_story_31530601_172_dialog_content = "I can help you enlist in our military and even start you off as a lieutenant!",
  ui_story_31530601_173_dialog_content = "... You want me to give you my home in exchange for working under you? What happened to not poking fun at your friends?!",
  ui_story_31530601_174_dialog_content = "Hahahahah!"
}
return config
